# TEST FIXTURE (id 95): trainers who see the hero (contract section 18), ground items, the respawn point. Not part of the game: reached only by the
# host harness (`make -C tools/host_world trainers`). column = i, row = j. Every trainer has a straight ray of 4 tiles (or 2, or blocked) along its
# facing: the screen-cardinal facings S E N W walk the tile diagonals (+1,+1) (+1,-1) (-1,-1) (-1,+1) (the 4-direction `rival` sprite), the odd facings
# SE NE NW SW walk the world axes (+i -j -i +j) (the 8-direction `vecino`).
@map test_trainers
@size 36 26
@interior no
@bg 0
@fill grass
@spawn start 1 1 S
@spawn see 7 7 S            # on the ray of trainer a: arriving here (a map load) is seen
@spawn center 16 10 N       # the respawn point the test script stores
@flag tt_beaten 220         # explicit beaten flag of trainer B (the test sets it)
@legend
  .  tile=grass
  r  object=rock
  a  npc=rival id=t_s face=S trainer=rival_lab text=tr.test.pre after=tr.test.after
  b  npc=rival id=t_e face=E trainer=rival_lab text=tr.test.pre after=tr.test.after
  c  npc=rival id=t_n face=N trainer=rival_lab text=tr.test.pre after=tr.test.after
  d  npc=rival id=t_w face=W trainer=rival_lab text=tr.test.pre after=tr.test.after
  e  npc=vecino id=t_se face=SE trainer=rival_lab text=tr.test.pre after=tr.test.after
  f  npc=vecino id=t_ne face=NE trainer=rival_lab text=tr.test.pre after=tr.test.after
  g  npc=vecino id=t_nw face=NW trainer=rival_lab text=tr.test.pre after=tr.test.after
  h  npc=vecino id=t_sw face=SW trainer=rival_lab                       # no text= / after=: the generic gl.trainer.pre / .after
  E  npc=vecino id=t_rock face=SE trainer=rival_lab text=tr.test.pre after=tr.test.after
  F  npc=vecino id=t_npc face=SE trainer=rival_lab text=tr.test.pre after=tr.test.after
  x  npc=vecino id=blocker face=S text=tr.test.after
  G  npc=rival id=t_flank face=S trainer=rival_lab text=tr.test.pre after=tr.test.after
  R  npc=rival id=t_r2 face=S trainer=rival_lab range=2 text=tr.test.pre after=tr.test.after
  B  npc=rival id=t_beaten face=E trainer=rival_lab text=tr.test.pre after=tr.test.after beaten_flag=tt_beaten
  i  item=salve
  j  item=antidote qty=2
@grid
  ....................................
  ....................................
  ..................................h.
  ....................................
  ....a.................B.............
  ....................................
  ..............b.....................
  ....................................
  ....................................
  ....................................
  ..E.r.......................c.......
  ....................................
  ....................................
  ..F.x...............................
  ............e...................g...
  ....................................
  ......d.............................
  ....................................
  ..........G...............R.........
  ............r.......................
  ................i...................
  ....................................
  ....................f...............
  ....................................
  ..................j.................
  ....................................
@script natives_test called
    # money: 3000 -> money_add 500 -> 3500 -> money_take 1000 (paid, var 5 = 1) -> 2500 -> money_take 2550 (not enough, var 6 = 0)
    money_add 500
    money_take 1000 5
    money_take 2550 6
    # bag: the test gives 1 Salve first; take_item takes it (var 7 = 1), the second time there is none (var 8 = 0); has_item
    has_item salve 9
    take_item salve 7
    take_item salve 8
    has_item salve 10
    # the respawn point of the blackout (18.3): this map, spawn `center`
    respawn center
@end
